import json, sys
path = sys.argv[1]
limit = int(sys.argv[2]) if len(sys.argv) > 2 else 400
for line in open(path, encoding="utf-8"):
    try:
        entry = json.loads(line)
    except json.JSONDecodeError:
        continue
    if entry.get("type") != "user" or entry.get("isMeta"):
        continue
    content = entry.get("message", {}).get("content")
    texts = []
    if isinstance(content, str):
        texts = [content]
    elif isinstance(content, list):
        texts = [c.get("text", "") for c in content if isinstance(c, dict) and c.get("type") == "text"]
    text = " ".join(t for t in texts if t and not t.startswith("<system-reminder>") and "<command-" not in t[:30]).strip()
    if not text or text.startswith("This session is being continued"):
        continue
    print(f"[{entry.get('timestamp', '')[:16]}] {text[:limit].replace(chr(10), ' / ')}\n")

